def generateSchedule(n):
    if n < 5:
        return []
    schedule = []
    last = None
    for d in range(1, n):
        if d == 1 or d == n - 1:
            order = list(range(0, n, 2)) + list(range(1, n, 2))
        else:
            order = list(range(n))
        shift = 0
        if last is not None:
            # rotate labels so the first match of this class is disjoint from the previous match
            for t in range(n):
                h = (order[0] + t) % n
                a = (h + d) % n
                if h not in last and a not in last:
                    shift = t
                    break
        for x in order:
            h = (x + shift) % n
            schedule.append([h, (h + d) % n])
        last = schedule[-1]
    return schedule
